import { createFileRoute } from '@tanstack/react-router';
import { GroupChatFloor } from '../../../../app/(sanctuary)/community/chat/[groupId]/GroupChatFloor';
import { SanctuaryShell } from '../../../../app/(sanctuary)/components/SanctuaryShell';

